func serviceLinks(lang, current string) []serviceLink {
	all := []serviceLink{{"Создание сайтов", "Лендинги и сайты компаний", "/websites"}, {"Разработка программ", "Веб-приложения и автоматизация", "/software"}, {"Дизайн наружной рекламы", "Баннеры, вывески и афиши", "/outdoor-advertising"}, {"Дизайн для компании", "Фирменная графика и рекламные материалы", "/business-design"}, {"Обложки и 3D", "Музыка, анимация и авторские работы", "/design"}}
	var links []serviceLink
	for _, link := range all {
		if link.URL == current {
			continue
		}
		link.Title = translate(lang, link.Title)
		link.Text = translate(lang, link.Text)
		link.URL = localizedURL(lang, link.URL)
		links = append(links, link)
	}
	return links
}
func localizeLanding(source *serviceLanding, lang string) *serviceLanding {
	if source == nil {
		return nil
	}
	result := *source
	result.Name = translate(lang, result.Name)
	result.IntroTitle = translate(lang, result.IntroTitle)
	result.IntroText = translate(lang, result.IntroText)
	result.DeliverablesTitle = translate(lang, result.DeliverablesTitle)
	result.Offers = append([]serviceOffer(nil), source.Offers...)
	for i := range result.Offers {
		result.Offers[i].Title = translate(lang, result.Offers[i].Title)
		result.Offers[i].Text = translate(lang, result.Offers[i].Text)
	}
	result.Deliverables = append([]string(nil), source.Deliverables...)
	for i := range result.Deliverables {
		result.Deliverables[i] = translate(lang, result.Deliverables[i])
	}
	result.FAQ = append([]serviceFAQ(nil), source.FAQ...)
	for i := range result.FAQ {
		result.FAQ[i].Question = translate(lang, result.FAQ[i].Question)
		result.FAQ[i].Answer = translate(lang, result.FAQ[i].Answer)
	}
	return &result
}
func publicPagePath(path string) bool {
	for _, page := range pages() {
		if page.ActivePath == path {
			return true
		}
	}
	return false
}
